import{_ as a,C as r,o,c as i,E as n,a2 as s}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"用户可见交付，不等于模型推理上下文","description":"","frontmatter":{"title":"用户可见交付，不等于模型推理上下文","date":"2026-08-19","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"How should a long-running agent system separate user-visible progress delivery from model reasoning context while preserving replayable delivery evidence?","summary":"用户收到了一条进度消息，不代表下一次模型请求就应把同样文本当作助手历史。Codex 当日合并变更展示了一个有界机制：异步消息以类型化交付记录进入协议和历史路径，但其可见文本不会被合成为下一轮模型上下文。","sources":["research/analysis/Q-20260819-02-delivery-context-separation.md"],"item_id":"Q-20260819-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-delivery-context-separation-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-08-19-delivery-context-separation.md","filePath":"zh/industry/2026-08-19-delivery-context-separation.md","lastUpdated":1787389481000}'),d={name:"zh/industry/2026-08-19-delivery-context-separation.md"};function l(c,e,p,u,h,m){const t=r("ArticleCover");return o(),i("div",null,[n(t,{image:"/assets/covers/daily-2026-08-19-delivery-context-separation-cover-v2.png",kicker:"行业架构 · 每日研究",title:"用户可见交付，不等于模型推理上下文",summary:"用户收到了一条进度消息，不代表下一次模型请求就应把同样文本当作助手历史。Codex 当日合并变更展示了一个有界机制：异步消息以类型化交付记录进入协议和历史路径，但其可见文本不会被合成为下一轮模型上下文。",version:"Q-20260819-02",status:"Daily Runtime V5 · 2026-08-19",languageHref:"/en/industry/2026-08-19-delivery-context-separation",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="用户可见交付-不等于模型推理上下文" tabindex="-1">用户可见交付，不等于模型推理上下文 <a class="header-anchor" href="#用户可见交付-不等于模型推理上下文" aria-label="Permalink to &quot;用户可见交付，不等于模型推理上下文&quot;">​</a></h1><p>长时间运行的智能体可能需要在工作尚未结束时告诉用户：“第一阶段已经完成，我会继续处理。”这条消息确实应进入用户可见历史，也应可供审计。但下一次模型请求是否必须把同样文本当作一条合成的助手消息重新读入？答案并不当然是“是”。</p><p>2026-08-19 合并的一项 Codex 变更把这两个问题拆开。新的 <code>send_user_message_async</code> 工具只允许根智能体使用，并受功能开关和模型支持门禁。有效调用会创建带 <code>delivery=Async</code> 分类的类型化 <code>AgentMessage</code> 项，等待本地 <code>ItemStarted</code> 与 <code>ItemCompleted</code> 发出后，向模型返回 <code>accepted=true</code>，当前回合可以继续。集成测试同时表明，这段用户可见文本不会作为合成助手消息回灌到下一次模型请求；协议、应用服务器和线程历史仍保留其交付分类。</p><p>这组证据支持一个架构判断：<strong>用户交付平面与模型推理上下文平面应当分离，但必须用稳定消息身份和可回放元数据保持关联。</strong></p><h2 id="用户看见了什么-与-模型依据什么推理-不是同一记录" tabindex="-1">“用户看见了什么”与“模型依据什么推理”不是同一记录 <a class="header-anchor" href="#用户看见了什么-与-模型依据什么推理-不是同一记录" aria-label="Permalink to &quot;“用户看见了什么”与“模型依据什么推理”不是同一记录&quot;">​</a></h2><p>用户交付回答的是通信事实：运行时尝试向谁发出什么内容，在何时通过哪类交付路径进入可见界面。模型上下文回答的是推理事实：哪些信息被明确允许进入后续模型请求，并可能影响下一步决策。</p><p>把两者压缩成一条统一对话记录会产生两个方向的错误。若所有用户可见消息都自动进入模型上下文，运行时产生的进度说明可能被模型误读为自身先前推理的一部分，重复内容并放大无关上下文。若为了避免污染而完全不保存消息，系统又失去“用户被告知了什么”的可回放证据。</p><p>分离平面并不是删除历史，而是承认历史有不同语义。交付记录可以持久存在，同时默认不被解释为下一轮模型输入。</p><h2 id="本地接收成功不是外部送达证明" tabindex="-1">本地接收成功不是外部送达证明 <a class="header-anchor" href="#本地接收成功不是外部送达证明" aria-label="Permalink to &quot;本地接收成功不是外部送达证明&quot;">​</a></h2><p>同日变更中的 <code>accepted=true</code> 有明确边界：处理器已接受调用，并完成已测试的本地项目生命周期发出。它不是外部传输回执，也不能证明用户设备已经显示、用户已经阅读，或失败后存在重试。</p><p>这一区分对自动化系统很关键。如果把本地工具返回成功直接写成“消息已送达”，监控与恢复逻辑会从错误事实出发。更稳健的状态至少应区分：</p><ul><li>工具调用被本地接收；</li><li>类型化消息项目已在运行时发出；</li><li>外部传输层已接受；</li><li>指定客户端已确认；</li><li>用户是否已读——如果系统确实具备且允许记录这种证据。</li></ul><p>当前代码直接支持前两项的有界证据，并保留交付分类。后续各项仍需要独立协议和回执。</p><h2 id="关联应依靠消息身份-而不是复制文本" tabindex="-1">关联应依靠消息身份，而不是复制文本 <a class="header-anchor" href="#关联应依靠消息身份-而不是复制文本" aria-label="Permalink to &quot;关联应依靠消息身份，而不是复制文本&quot;">​</a></h2><p>分离之后，系统仍要回答一条用户可见消息与哪次工作进度相关。可复用做法是给消息稳定身份，并让运行时项目、传输尝试、客户端回执和线程历史引用同一身份。</p><p>这样，审计器可以重建“系统何时告诉了用户什么”，却不会暗示模型随后一定基于同样文本进行推理。若后续工作确实需要知道“用户已经收到第一阶段结果”，应由显式工作流状态或记忆机制把这个事实带入上下文，并同时保留其来源与范围，而不是依赖消息文本偶然被回灌。</p><p>这一设计也有利于压缩和恢复。上下文可以根据推理需要裁剪，交付账本则按审计和重放要求保存；二者通过身份关联，而不必共享完全相同的保留策略。</p><h2 id="分离平面并不会自动提供可靠消息系统" tabindex="-1">分离平面并不会自动提供可靠消息系统 <a class="header-anchor" href="#分离平面并不会自动提供可靠消息系统" aria-label="Permalink to &quot;分离平面并不会自动提供可靠消息系统&quot;">​</a></h2><p>现有证据来自一个公开仓库的已合并实现及集成测试，不是对端到端通知可靠性的独立研究。已演示顺序局限于本地处理器、事件和下一次模型请求路径。</p><p>它没有建立跨客户端全局顺序、取消、幂等去重、自动重试、最终用户确认或“仅一次”交付。历史路径保留类型化项目，也不等于所有崩溃情形下都具备无限期持久性。</p><p>因此不能从“消息没有污染模型上下文”进一步推导“异步交付已经可靠”。分离解决的是语义和证据边界；可靠传输仍需要自己的状态机、回执和恢复策略。</p><p>接下来的工程问题应落在可验证接口上：哪个组件拥有最终用户交付回执？重试如何继续引用原消息身份并抑制重复？当后续推理确实需要某个已交付事实时，谁有权把它写入记忆或工作流状态？只有分别回答这些问题，系统才能既向用户持续报告进度，又不把通信历史误写成模型的推理历史。</p><p><strong>一手证据：</strong> <a href="https://github.com/openai/codex/commit/71dbf72b0576f9e7be1ef28d275bc79ece6d4b6c" target="_blank" rel="noreferrer">OpenAI Codex 合并提交 71dbf72b</a>。代码与仓库测试属于公开一手证据，不构成端到端交付可靠性的独立验证。</p>',23))])}const v=a(d,[["render",l]]);export{y as __pageData,v as default};
